'use strict';
function sampleHeap() {
  const m = process.memoryUsage();
  return { heapUsed: m.heapUsed, heapTotal: m.heapTotal, rss: m.rss };
}
function growthRate(samples) {
  if (samples.length < 2) return 0;
  return samples[samples.length - 1].heapUsed - samples[0].heapUsed;
}
module.exports = { sampleHeap, growthRate };

'use strict';
function estimateComplexity(sizes, timings) {
  const ratios = [];
  for (let i = 1; i < sizes.length; i += 1) {
    const sizeR = sizes[i] / sizes[i - 1];
    const timeR = timings[i] / timings[i - 1];
    ratios.push(Math.log(timeR) / Math.log(sizeR));
  }
  const exp = ratios.reduce((s, r) => s + r, 0) / ratios.length;
  return { exponent: exp, quadratic: exp >= 1.8 };
}
module.exports = { estimateComplexity };

'use strict';
function suggestIndexes(queries) {
  const counts = {};
  for (const q of queries) {
    for (const col of q.where || []) counts[col] = (counts[col] || 0) + 1;
  }
  return Object.keys(counts).filter((c) => counts[c] >= 2).sort();
}
module.exports = { suggestIndexes };

'use strict';
function createLoadShedder(maxConcurrent) {
  let inFlight = 0;
  return {
    admit() {
      if (inFlight >= maxConcurrent) return false;
      inFlight += 1;
      return true;
    },
    complete() { if (inFlight > 0) inFlight -= 1; },
    saturated() { return inFlight >= maxConcurrent; },
  };
}
module.exports = { createLoadShedder };

'use strict';
function coalesce(requests, keyFn) {
  const seen = new Map();
  for (const req of requests) {
    const key = keyFn(req);
    if (!seen.has(key)) seen.set(key, req);
  }
  return Array.from(seen.values());
}
module.exports = { coalesce };
